journals.script:
{
is_shown_when_inactive = {
	has_variable = ywc_v03_initialized
	NOT = { has_variable = ywc_c04_started }
	OR = {
		AND = { c:JHG ?= this OR = { ywc_c04_case_ready_jhg = yes var:ywc_c04_case_open ?= 1 } } 
		AND = { c:DMG ?= this OR = { ywc_c04_case_ready_dmg = yes var:ywc_c04_case_open ?= 1 } } 
		AND = { c:LAN ?= this OR = { ywc_c04_case_ready_lan = yes var:ywc_c04_case_open ?= 1 } } 
		AND = { c:WBK ?= this var:ywc_c04_case_open ?= 1 } 
		AND = { c:MHG ?= this var:ywc_c04_case_open ?= 1 }
	}
}
possible = {
	has_variable = ywc_v03_initialized
	ywc_v03_has_capacity = yes
	NOT = { has_variable = ywc_c04_started }
	OR = {
		AND = { c:JHG ?= this OR = { ywc_c04_case_ready_jhg = yes var:ywc_c04_case_open ?= 1 } } 
		AND = { c:DMG ?= this OR = { ywc_c04_case_ready_dmg = yes var:ywc_c04_case_open ?= 1 } } 
		AND = { c:LAN ?= this OR = { ywc_c04_case_ready_lan = yes var:ywc_c04_case_open ?= 1 } } 
		AND = { c:WBK ?= this var:ywc_c04_case_open ?= 1 } 
		AND = { c:MHG ?= this var:ywc_c04_case_open ?= 1 }
	}
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c04_started } }
		set_variable = { name = ywc_c04_started value = 1 }
		set_variable = { name = ywc_c04_popup_epoch value = 0 }
		set_variable = { name = ywc_c04_wait_age value = 0 }
		change_variable = { name = ywc_v03_active_arc_count add = 1 }
		change_variable = { name = ywc_v03_visible_task_count add = 1 }
	}
	if = { limit = { NOT = { has_variable = ywc_c04_popup_epoch } } set_variable = { name = ywc_c04_popup_epoch value = 0 } }
	if = { limit = { c:JHG ?= this NOT = { has_variable = ywc_c04_role } } set_variable = { name = ywc_c04_role value = 1 } }
	if = { limit = { c:DMG ?= this NOT = { has_variable = ywc_c04_role } } set_variable = { name = ywc_c04_role value = 2 } }
	if = { limit = { c:LAN ?= this NOT = { has_variable = ywc_c04_role } } set_variable = { name = ywc_c04_role value = 3 } }
	if = { limit = { c:WBK ?= this NOT = { has_variable = ywc_c04_role } } set_variable = { name = ywc_c04_role value = 5 } }
	if = { limit = { c:MHG ?= this NOT = { has_variable = ywc_c04_role } } set_variable = { name = ywc_c04_role value = 6 } }
	if = { limit = { OR = { var:ywc_c04_role ?= 1 var:ywc_c04_role ?= 2 var:ywc_c04_role ?= 3 } NOT = { has_variable = ywc_c04_stage } }
		set_variable = { name = ywc_c04_case_open value = 1 }
		set_variable = { name = ywc_c04_stage value = 1300 }
		set_variable = { name = ywc_c04_pending value = 1300 }
	}
	if = { limit = { OR = { var:ywc_c04_role ?= 4 var:ywc_c04_role ?= 5 var:ywc_c04_role ?= 6 } NOT = { has_variable = ywc_c04_stage } } set_variable = { name = ywc_c04_stage value = 1318 } }
	# Cross-mount the other cores while this holder is the organizing side, so
	# their journal can activate before the response round opens (each mounted
	# country then waits at 1318 with its own monthly fallback).
	if = { limit = { c:JHG ?= this c:DMG ?= { is_country_alive = yes NOT = { has_variable = ywc_c04_case_open } NOT = { has_variable = ywc_c04_started } NOT = { has_variable = ywc_c04_outcome } } }
		c:DMG = { set_variable = { name = ywc_c04_case_open value = 1 } set_variable = { name = ywc_c04_role value = 4 } set_variable = { name = ywc_c04_popup_epoch value = 0 } set_variable = { name = ywc_c04_wait_age value = 0 } set_variable = { name = ywc_c04_stage value = 1318 } } }
	if = { limit = { c:JHG ?= this c:LAN ?= { is_country_alive = yes NOT = { has_variable = ywc_c04_case_open } NOT = { has_variable = ywc_c04_started } NOT = { has_variable = ywc_c04_outcome } } }
		c:LAN = { set_variable = { name = ywc_c04_case_open value = 1 } set_variable = { name = ywc_c04_role value = 4 } set_variable = { name = ywc_c04_popup_epoch value = 0 } set_variable = { name = ywc_c04_wait_age value = 0 } set_variable = { name = ywc_c04_stage value = 1318 } } }
	if = { limit = { c:DMG ?= this c:JHG ?= { is_country_alive = yes NOT = { has_variable = ywc_c04_case_open } NOT = { has_variable = ywc_c04_started } NOT = { has_variable = ywc_c04_outcome } } }
		c:JHG = { set_variable = { name = ywc_c04_case_open value = 1 } set_variable = { name = ywc_c04_role value = 4 } set_variable = { name = ywc_c04_popup_epoch value = 0 } set_variable = { name = ywc_c04_wait_age value = 0 } set_variable = { name = ywc_c04_stage value = 1318 } } }
	if = { limit = { c:DMG ?= this c:LAN ?= { is_country_alive = yes NOT = { has_variable = ywc_c04_case_open } NOT = { has_variable = ywc_c04_started } NOT = { has_variable = ywc_c04_outcome } } }
		c:LAN = { set_variable = { name = ywc_c04_case_open value = 1 } set_variable = { name = ywc_c04_role value = 4 } set_variable = { name = ywc_c04_popup_epoch value = 0 } set_variable = { name = ywc_c04_wait_age value = 0 } set_variable = { name = ywc_c04_stage value = 1318 } } }
	if = { limit = { c:LAN ?= this c:JHG ?= { is_country_alive = yes NOT = { has_variable = ywc_c04_case_open } NOT = { has_variable = ywc_c04_started } NOT = { has_variable = ywc_c04_outcome } } }
		c:JHG = { set_variable = { name = ywc_c04_case_open value = 1 } set_variable = { name = ywc_c04_role value = 4 } set_variable = { name = ywc_c04_popup_epoch value = 0 } set_variable = { name = ywc_c04_wait_age value = 0 } set_variable = { name = ywc_c04_stage value = 1318 } } }
	if = { limit = { c:LAN ?= this c:DMG ?= { is_country_alive = yes NOT = { has_variable = ywc_c04_case_open } NOT = { has_variable = ywc_c04_started } NOT = { has_variable = ywc_c04_outcome } } }
		c:DMG = { set_variable = { name = ywc_c04_case_open value = 1 } set_variable = { name = ywc_c04_role value = 4 } set_variable = { name = ywc_c04_popup_epoch value = 0 } set_variable = { name = ywc_c04_wait_age value = 0 } set_variable = { name = ywc_c04_stage value = 1318 } } }
}
on_monthly_pulse = {
	effect = {
		# Organizer awaiting the response round (1313): resolved or 12 months.
		if = { limit = { OR = { var:ywc_c04_role ?= 1 var:ywc_c04_role ?= 2 var:ywc_c04_role ?= 3 } var:ywc_c04_stage ?= 1313 }
			change_variable = { name = ywc_c04_wait_age add = 1 }
			if = { limit = { OR = { ywc_c04_responses_resolved = yes var:ywc_c04_wait_age >= 12 } } ywc_c04_init_after_responses = yes }
		}
		# Mounted countries still waiting for the opening (1318): organizer gone or
		# 24 months, then close as no-talks on their own.
		if = { limit = { OR = { var:ywc_c04_role ?= 4 var:ywc_c04_role ?= 5 var:ywc_c04_role ?= 6 } var:ywc_c04_stage ?= 1318 }
			change_variable = { name = ywc_c04_wait_age add = 1 }
			if = { limit = { OR = { ywc_c04_organizer_gone = yes var:ywc_c04_wait_age >= 24 } } ywc_c04_close_no_talks = yes }
		}
		# Answer stages whose organizer stopped waiting: close on their own.
		if = { limit = { OR = { var:ywc_c04_stage ?= 1302 var:ywc_c04_stage ?= 1303 } NOT = { ywc_c04_organizer_awaiting_responses = yes } } ywc_c04_close_no_talks = yes }
		if = { limit = { ywc_c04_jhg_delivery_1300 = yes } trigger_event = { id = ywc_crisis.1300 } }
		if = { limit = { ywc_c04_dmg_delivery_1300 = yes } trigger_event = { id = ywc_crisis.1300 } }
		if = { limit = { ywc_c04_lan_delivery_1300 = yes } trigger_event = { id = ywc_crisis.1300 } }
		if = { limit = { ywc_c04_jhg_delivery_1301 = yes } trigger_event = { id = ywc_crisis.1301 } }
		if = { limit = { ywc_c04_dmg_delivery_1301 = yes } trigger_event = { id = ywc_crisis.1301 } }
		if = { limit = { ywc_c04_lan_delivery_1301 = yes } trigger_event = { id = ywc_crisis.1301 } }
		if = { limit = { ywc_c04_dmg_delivery_1302 = yes } trigger_event = { id = ywc_crisis.1302 } }
		if = { limit = { ywc_c04_lan_delivery_1302 = yes } trigger_event = { id = ywc_crisis.1302 } }
		if = { limit = { ywc_c04_wbk_delivery_1303 = yes } trigger_event = { id = ywc_crisis.1303 } }
		if = { limit = { ywc_c04_mhg_delivery_1303 = yes } trigger_event = { id = ywc_crisis.1303 } }
	}
}
}

{
is_shown_when_inactive = { has_variable = ywc_c04_escort_open }
possible = {
	has_variable = ywc_v03_initialized
	has_variable = ywc_c04_started
	var:ywc_c04_escort_open ?= 1
	OR = { c:JHG ?= this c:DMG ?= this c:LAN ?= this c:WBK ?= this c:MHG ?= this }
	NOT = { has_variable = ywc_c04_outcome }
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c04_popup_epoch } } set_variable = { name = ywc_c04_popup_epoch value = 0 } }
}
on_monthly_pulse = {
	effect = {
		# Organizer awaiting the seizure answers (1317): resolved or 18 months,
		# then walk to the flag check on its own.
		if = { limit = { OR = { var:ywc_c04_role ?= 1 var:ywc_c04_role ?= 2 var:ywc_c04_role ?= 3 } var:ywc_c04_stage ?= 1317 }
			change_variable = { name = ywc_c04_wait_age add = 1 }
			if = { limit = { OR = { ywc_c04_seizure_resolved = yes var:ywc_c04_wait_age >= 18 } }
				set_variable = { name = ywc_c04_stage value = 1307 }
				set_variable = { name = ywc_c04_pending value = 1307 }
				set_variable = { name = ywc_c04_wait_age value = 0 }
				change_variable = { name = ywc_c04_popup_epoch add = 1 }
			}
		}
		# Stranded seizure answerers when the organizer is gone: close on their own.
		if = { limit = { OR = { var:ywc_c04_stage ?= 1306 var:ywc_c04_stage ?= 1314 } ywc_c04_organizer_gone = yes } ywc_c04_close_no_talks = yes }
		if = { limit = { ywc_c04_jhg_delivery_1304 = yes } trigger_event = { id = ywc_crisis.1304 } }
		if = { limit = { ywc_c04_dmg_delivery_1304 = yes } trigger_event = { id = ywc_crisis.1304 } }
		if = { limit = { ywc_c04_lan_delivery_1304 = yes } trigger_event = { id = ywc_crisis.1304 } }
		if = { limit = { ywc_c04_wbk_delivery_1305 = yes } trigger_event = { id = ywc_crisis.1305 } }
		if = { limit = { ywc_c04_mhg_delivery_1305 = yes } trigger_event = { id = ywc_crisis.1305 } }
		if = { limit = { ywc_c04_wbk_delivery_1306 = yes } trigger_event = { id = ywc_crisis.1306 } }
		if = { limit = { ywc_c04_mhg_delivery_1306 = yes } trigger_event = { id = ywc_crisis.1306 } }
		if = { limit = { ywc_c04_dmg_delivery_1314 = yes } trigger_event = { id = ywc_crisis.1306 } }
		if = { limit = { ywc_c04_lan_delivery_1314 = yes } trigger_event = { id = ywc_crisis.1306 } }
		if = { limit = { ywc_c04_jhg_delivery_1307 = yes } trigger_event = { id = ywc_crisis.1307 } }
		if = { limit = { ywc_c04_dmg_delivery_1307 = yes } trigger_event = { id = ywc_crisis.1307 } }
		if = { limit = { ywc_c04_lan_delivery_1307 = yes } trigger_event = { id = ywc_crisis.1307 } }
	}
}
}

{
is_shown_when_inactive = { has_variable = ywc_c04_review_open }
possible = {
	has_variable = ywc_v03_initialized
	has_variable = ywc_c04_started
	var:ywc_c04_review_open ?= 1
	OR = { c:JHG ?= this c:DMG ?= this c:LAN ?= this c:WBK ?= this c:MHG ?= this }
	NOT = { has_variable = ywc_c04_outcome }
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c04_popup_epoch } } set_variable = { name = ywc_c04_popup_epoch value = 0 } }
}
on_monthly_pulse = {
	effect = {
		# Organizer awaiting the renegotiation answers (1320): resolved or 12
		# months, then open the settlement round for everyone still in the case.
		if = { limit = { OR = { var:ywc_c04_role ?= 1 var:ywc_c04_role ?= 2 var:ywc_c04_role ?= 3 } var:ywc_c04_stage ?= 1320 }
			change_variable = { name = ywc_c04_wait_age add = 1 }
			if = { limit = { OR = { ywc_c04_renegotiation_resolved = yes var:ywc_c04_wait_age >= 12 } } ywc_c04_open_settlement = yes }
		}
		# Waiting for the renegotiation window or the settlement round (1319/1321):
		# organizer gone or 36 months, then settle on their own.
		if = { limit = { OR = { var:ywc_c04_stage ?= 1319 var:ywc_c04_stage ?= 1321 } }
			change_variable = { name = ywc_c04_wait_age add = 1 }
			if = { limit = { OR = { ywc_c04_organizer_gone = yes var:ywc_c04_wait_age >= 36 } } ywc_c04_self_settle = yes }
		}
		# Renegotiation answer stages stranded by a dead organizer: settle on their own.
		if = { limit = { OR = { var:ywc_c04_stage ?= 1316 var:ywc_c04_stage ?= 1309 } ywc_c04_organizer_gone = yes } ywc_c04_self_settle = yes }
		if = { limit = { ywc_c04_jhg_delivery_1308 = yes } trigger_event = { id = ywc_crisis.1308 } }
		if = { limit = { ywc_c04_dmg_delivery_1308 = yes } trigger_event = { id = ywc_crisis.1308 } }
		if = { limit = { ywc_c04_lan_delivery_1308 = yes } trigger_event = { id = ywc_crisis.1308 } }
		if = { limit = { ywc_c04_dmg_delivery_1316 = yes } trigger_event = { id = ywc_crisis.1308 } }
		if = { limit = { ywc_c04_lan_delivery_1316 = yes } trigger_event = { id = ywc_crisis.1308 } }
		if = { limit = { ywc_c04_wbk_delivery_1309 = yes } trigger_event = { id = ywc_crisis.1309 } }
		if = { limit = { ywc_c04_mhg_delivery_1309 = yes } trigger_event = { id = ywc_crisis.1309 } }
		if = { limit = { ywc_c04_jhg_delivery_1310 = yes } trigger_event = { id = ywc_crisis.1310 } }
		if = { limit = { ywc_c04_dmg_delivery_1310 = yes } trigger_event = { id = ywc_crisis.1310 } }
		if = { limit = { ywc_c04_lan_delivery_1310 = yes } trigger_event = { id = ywc_crisis.1310 } }
		if = { limit = { ywc_c04_wbk_delivery_1310 = yes } trigger_event = { id = ywc_crisis.1310 } }
		if = { limit = { ywc_c04_mhg_delivery_1310 = yes } trigger_event = { id = ywc_crisis.1310 } }
		if = { limit = { ywc_c04_jhg_delivery_1311 = yes } trigger_event = { id = ywc_crisis.1311 } }
		if = { limit = { ywc_c04_dmg_delivery_1311 = yes } trigger_event = { id = ywc_crisis.1311 } }
		if = { limit = { ywc_c04_lan_delivery_1311 = yes } trigger_event = { id = ywc_crisis.1311 } }
		if = { limit = { ywc_c04_wbk_delivery_1311 = yes } trigger_event = { id = ywc_crisis.1311 } }
		if = { limit = { ywc_c04_mhg_delivery_1311 = yes } trigger_event = { id = ywc_crisis.1311 } }
	}
}
}
